var DirectoryMemberAPI = Class.create();
DirectoryMemberAPI.CONSTANTS = {
    API_CONFIG: {
        GET_MEMBER_DETAILS: {
            path: "/admin/directory/v1/groups/${groupKey}/members/${memberKey}",
            httpMethod: "GET",
            pathParams: ["memberKey", "userKey"]
        },
        LIST_MEMBERS: {
            path: "/admin/directory/v1/groups/${groupKey}/members",
            httpMethod: "GET",
            pathParams: ["memberKey"]
        },
        INSERT: {
            path: "/admin/directory/v1/groups/${groupKey}/members",
            httpMethod: "POST",
            pathParams: ["groupKey"],
            content: {
                kind: {
                    required: true,
                    defaultValue: "admin#directory#member"
                },
                email: {
                    required: true
                },
                role: {
                    required: true,
                    enum: ["MANAGER", "MEMBER", "OWNER"]
                },
                type: {
                    required: true,
                    enum: ["CUSTOMER", "EXTERNAL", "GROUP", "USER"]
                },
                delivery_settings: {
                    required: true,
                    enum: ["ALL_MAIL", "DAILY", "DIGEST", "DISABLED", "NONE"]
                }
            }
        }
    }
};
DirectoryMemberAPI.prototype = Object.extend(new x_neyu_google_nyu.AuthUtil(), {
    initialize: function() {
        this.oauthProvider = "8491b701ebcf7a105c06fcffcad0cda8";
        this.providerProfile = "3b683f45ebcf7a105c06fcffcad0cd99";
        this.credential = gs.getProperty("x_neyu_google_nyu.directory.api.credential.id");
        this.aliasId = "1249fca42b94c3508a69f0dcce91bf0f";
    },


    /**
     * Retrieves a group member's properties
     * 
     * @param groupKey {string} - unique identifier for the group
     * @param memberKey {string} - unique identifier for the user
     */
    getMemberDetails: function(groupKey, memberKey) {
        gs.info("[getMemberDetails]\nGroup Key: {0}\nMemberKey: {1}",
            groupKey, memberKey);

        if (!groupKey || !memberKey) {
            return {
                error: true,
                errorMessage: "groupKey and memberKey are required"
            };
        }

        this.ensureToken(this.credential, this.oauthProvider, this.providerProfile);

        const pathParams = {
            groupKey: groupKey,
            memberKey: memberKey
        };
        const config = DirectoryMemberAPI.CONSTANTS.API_CONFIG.GET_MEMBER_DETAILS;
        const requestConfig = {
            ...config,
            pathParams,
            aliasId: this.aliasId
        };

        const response = this.execute(requestConfig, "getMemberDetails");

        if (response.error) {
            gs.error("[getMemberDetails] There was an error returned from the " +
                "Google Directories API. \nError: " + response.errorMessage);
        }

        return {
            ...response
        };
    },

    /**
     * Retrieves the list of members for a group
     * 
     * @param groupKey {string} - unique identifier for the group
     */
    listMembers: function(groupKey) {
        gs.info("[listMembers]\nGroup Key: {0}", groupKey);

        if (!groupKey) {
            return {
                error: true,
                errorMessage: "groupKey is required"
            };
        }

        this.ensureToken(this.credential, this.oauthProvider, this.providerProfile);

        const pathParams = {
            groupKey: groupKey
        };
        const config = DirectoryMemberAPI.CONSTANTS.API_CONFIG.LIST_MEMBERS;
        const requestConfig = {
            ...config,
            pathParams,
            aliasId: this.aliasId
        };

        const response = this.execute(requestConfig, "listMembers");

        if (response.error && response?.status != 500) {
            gs.error("[listMembers] There was an error returned from the " +
                "Google Directories API. \nResponse: " + JSON.stringify(response));
        }

        return {
            ...response
        };
    },

    /**
     * Inserts a user into a group
     * 
     * @param groupkey {string} - the unique ID of the group
     * @param userId {string} - the email address or unique ID of the user
     * @param type {string} - the type of group member, can be CUSTOMER, EXTERNAL, GROUP, or USER. Defaults to USER
     * @param role {string} - whether the user is an owner, manager, or member. Defaults to Member
     * @param deliverySettings {string} - how often the user should receive mail from the group, defaults to ALL_MAIL
     */
    insert: function(groupKey, userId, {
        kind = "admin#directory#member",
        type = "USER",
        role = "MEMBER",
        deliverySettings = "ALL_MAIL"
    }) {
        gs.info("[addMember]\ngroupKey: " + groupKey +
            "\nuserId: " + userId +
            "\nkind: " + kind +
            "\ntype: " + type +
            "\nrole: " + role +
            "\ndeliverySettings: " + deliverySettings);

        if (!groupKey || !userId || !kind || !type || !role || !deliverySettings) {
            return {
                error: true,
                errorMessage: "There are empty required parameters"
            };
        }

        this.ensureToken(this.credential, this.oauthProvider, this.providerProfile);

        const config = DirectoryMemberAPI.CONSTANTS.API_CONFIG.INSERT;
        const content = {
            email: userId,
            kind: kind,
            type: type,
            role: role,
            delivery_settings: deliverySettings
        };

        const errors = this.validateContent(...config.content, content);

        const pathParams = {
            groupKey: groupKey
        };
        const requestConfig = {
            ...config,
            pathParams,
            content: JSON.stringify(content),
            aliasId: this.aliasId
        };

		const response = this.execute(requestConfig, "insert");

		if (response.error && response?.status != 500) {
			gs.error(`[insert] There was an error returned from the` +
				`Google Directories API.\nResponse: ${JSON.stringify(response)}`);
		}

		return {
			...response
		};
    },


    /**
     * Helper function to enable unit testing
     */
    execute: function(requestConfig, caller) {
        const builder = new x_neyu_rest_utils.RequestBuilder(requestConfig);
        const api = new x_neyu_rest_utils.WebServiceUtil();

        try {
            return api.executeRestMessage(builder.build());
        } catch (ex) {
            gs.error(`[${caller}] There was an internal error building ` +
                "and executing the RestMessage.\nError: " + ex);
            return {
                error: true,
				status: 500,
                errorMessage: ex + ""
            };
        }
    },

    validateContent: function(spec, content) {
        // get all the parameters in the spec that are marked as required
        const missingRequiredKeys = Object.fromEntries(
            Object.entries(spec).filter(([k, v]) => v?.required)
            .filter(([k, v]) => !Object.keys(content).includes(k))
            .map(([k, _]) => {
                return [
                    k,
                    {
                        error: `Missing required input '${k}'`
                    }
                ];
            })
        );

        if (Object.keys(missingRequiredKeys).length > 0) {
            return missingRequiredKeys;
        }

        // validate that there aren't extra keys
        const invalidInputs = Object.fromEntries(
            Object.entries(content).filter(([k, v]) => !Object.keys(spec).includes(k))
            .map(([k, v]) => {
                return [
                    k,
                    {
                        value: v,
                        error: `Property '${k}' is not a valid input`
                    }
                ];
            })
        );
        if (Object.keys(invalidInputs).length > 0) {
            return invalidInputs;
        }

        // get all the parameters from the spec that have a defined enum
        const restrictedInputs = Object.fromEntries(Object.entries(spec)
            .filter(([k, v]) => v?.enum));
        // find any key:value pairs where the value does not match any of the enum values
        const invalidValues = Object.fromEntries(
            Object.entries(content)
            .filter(([k, v]) => restrictedInputs[k] && !restrictedInputs[k]?.enum.includes(v))
            .map(([k, v]) => {
                return [
                    k,
                    {
                        value: v,
                        error: `Value '${v}' is not a valid input for property '${k}'`
                    }
                ];
            })
        );

        if (Object.keys(invalidValues).length > 0) {
            return invalidValues;
        }
        return null;
    },

    type: 'DirectoryMemberAPI'
});
